SET WORKSPACE_DB = 'INTELLIGENCE_WORKSPACE_DEMO';
SET WORKSPACE_WAREHOUSE = CURRENT_WAREHOUSE();
SET WORKSPACE_POOL = '';
SET WORKSPACE_PACKAGE_EAI = '';
SET WORKSPACE_RUNTIME_ROLE = 'WORKSPACE_EXECUTIVE_RUNTIME';
SET WORKSPACE_PROVISIONER_ROLE = 'WORKSPACE_EXECUTIVE_PROVISIONER';
SET WORKSPACE_INSTALL = FALSE;
SET WORKSPACE_HOST = FALSE;
SET WORKSPACE_AI = FALSE;
SELECT 'Synthetic-data demo only. This does not discover or connect your business data. Review AI answers against query evidence. Requires a non-trial AWS/Azure account supporting hybrid tables and an installer role allowed to create an isolated database/roles and grant warehouse, Cortex and host privileges. Choose an existing warehouse above. For HOST set an approved package EAI; an empty pool selects the account default. AI uses Opus 5 for the portfolio and auto for specialists; model availability depends on account/region. No settings, compute or integrations are created outside the isolated demo roles/database. Existing shared compute settings stay unchanged. INSTALL/AI/HOST default FALSE. Usage incurs warehouse, container, storage and AI charges; no free or fixed-cost claim. Messages stay disabled. Reset and teardown require explicit confirmation; roles and shared compute are retained.' AS PREFLIGHT;
EXECUTE IMMEDIATE $$
DECLARE
database_name VARCHAR := $WORKSPACE_DB;
warehouse_name VARCHAR := COALESCE($WORKSPACE_WAREHOUSE,'');
pool_name VARCHAR := COALESCE($WORKSPACE_POOL,'');
eai_name VARCHAR := COALESCE($WORKSPACE_PACKAGE_EAI,'');
runtime_role VARCHAR := $WORKSPACE_RUNTIME_ROLE;
provisioner_role VARCHAR := $WORKSPACE_PROVISIONER_ROLE;
source_revision VARCHAR := 'b44d441e013668c5';
installer_role VARCHAR := CURRENT_ROLE();
command VARCHAR;
source_text VARCHAR;
existing_count INTEGER;
foreign_count INTEGER;
role_count INTEGER;
ai_status VARCHAR := 'disabled';
host_status VARCHAR := 'disabled';
BEGIN
IF (NOT $WORKSPACE_INSTALL) THEN
    RETURN OBJECT_CONSTRUCT('status','preflight_only','objects_created',0,'data','synthetic only','source_release',source_revision,'enable','Review prerequisites, then set INSTALL, AI and HOST independently.');
END IF;
IF (NOT REGEXP_LIKE(database_name,'^[A-Z][A-Z0-9_]{0,70}$')
    OR NOT REGEXP_LIKE(warehouse_name,'^[A-Z][A-Z0-9_]{0,100}$')
    OR NOT REGEXP_LIKE(runtime_role,'^[A-Z][A-Z0-9_]{0,100}$')
    OR NOT REGEXP_LIKE(provisioner_role,'^[A-Z][A-Z0-9_]{0,100}$')
    OR runtime_role=provisioner_role
    OR runtime_role IN ('ACCOUNTADMIN','SECURITYADMIN','SYSADMIN','USERADMIN','PUBLIC','ORGADMIN')
    OR provisioner_role IN ('ACCOUNTADMIN','SECURITYADMIN','SYSADMIN','USERADMIN','PUBLIC','ORGADMIN')) THEN
    RETURN 'Invalid configured identifiers or reserved roles. No changes.';
END IF;
command := 'SHOW WAREHOUSES LIKE ' || CHR(39) || warehouse_name || CHR(39);
EXECUTE IMMEDIATE :command;
SELECT COUNT(*) INTO :existing_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=:warehouse_name;
IF (existing_count<>1) THEN RETURN 'Configured warehouse is not visible. Select an existing approved warehouse; no changes made.'; END IF;
IF ($WORKSPACE_HOST) THEN
    IF (pool_name='') THEN
        SHOW PARAMETERS LIKE 'DEFAULT_STREAMLIT_COMPUTE_POOL' IN ACCOUNT;
        SELECT COALESCE(NULLIF("value",''),"default") INTO :pool_name FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "key"='DEFAULT_STREAMLIT_COMPUTE_POOL';
    END IF;
    IF (NOT REGEXP_LIKE(pool_name,'^[A-Z][A-Z0-9_]{0,100}$') OR NOT REGEXP_LIKE(eai_name,'^[A-Z][A-Z0-9_]{0,100}$')) THEN
        RETURN 'HOST requires an approved compute pool and package external access integration. Set WORKSPACE_PACKAGE_EAI; no changes made.';
    END IF;
    command := 'SHOW COMPUTE POOLS LIKE ' || CHR(39) || pool_name || CHR(39);
    EXECUTE IMMEDIATE :command;
    SELECT COUNT(*) INTO :existing_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=:pool_name;
    IF (existing_count<>1) THEN RETURN 'Configured compute pool is not visible; no changes made.'; END IF;
    command := 'SHOW INTEGRATIONS LIKE ' || CHR(39) || eai_name || CHR(39);
    EXECUTE IMMEDIATE :command;
    SELECT COUNT(*) INTO :existing_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=:eai_name AND "type"='EXTERNAL_ACCESS' AND "enabled"::BOOLEAN;
    IF (existing_count<>1) THEN RETURN 'Configured package integration is missing or disabled; no changes made.'; END IF;
END IF;
command := 'SHOW DATABASES LIKE ' || CHR(39) || database_name || CHR(39);
EXECUTE IMMEDIATE :command;
SELECT COUNT(*),COUNT_IF(COALESCE("comment",'') NOT LIKE '%workspace-executive-workspace:v1%') INTO :existing_count,:foreign_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=:database_name;
IF (foreign_count>0) THEN RETURN 'Target database is not registered to this installer. Choose a new database; no changes made.'; END IF;
IF (existing_count=0) THEN
    command := 'SHOW ROLES LIKE ' || CHR(39) || runtime_role || CHR(39);
    EXECUTE IMMEDIATE :command;
    SELECT COUNT(*) INTO :role_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=:runtime_role;
    IF (role_count>0) THEN RETURN 'Runtime role already exists. Choose a new isolated role; no changes made.'; END IF;
    command := 'SHOW ROLES LIKE ' || CHR(39) || provisioner_role || CHR(39);
    EXECUTE IMMEDIATE :command;
    SELECT COUNT(*) INTO :role_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=:provisioner_role;
    IF (role_count>0) THEN RETURN 'Provisioner role already exists. Choose a new isolated role; no changes made.'; END IF;
END IF;
command := BASE64_DECODE_STRING('Q1JFQVRFIERBVEFCQVNFIElGIE5PVCBFWElTVFMgJHtEQVRBQkFTRX0gQ09NTUVOVD0nd29ya3NwYWNlLWV4ZWN1dGl2ZS13b3Jrc3BhY2U6djEn');
command := REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(command,'${DATABASE}',database_name),'${WAREHOUSE}',warehouse_name),'${POOL}',pool_name),'${EAI}',eai_name),'${RUNTIME}',runtime_role),'${PROVISIONER}',provisioner_role);
EXECUTE IMMEDIATE :command;
command := BASE64_DECODE_STRING('Q1JFQVRFIFJPTEUgSUYgTk9UIEVYSVNUUyAke1JVTlRJTUV9');
command := REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(command,'${DATABASE}',database_name),'${WAREHOUSE}',warehouse_name),'${POOL}',pool_name),'${EAI}',eai_name),'${RUNTIME}',runtime_role),'${PROVISIONER}',provisioner_role);
EXECUTE IMMEDIATE :command;
